  /** Przyjmuje polecenie glosowe wydane w nakladce i kieruje je do asystenta */
  'aod.voice.command': { request: AodVoiceCommandRequest; response: AodVoiceCommandResponse };
  /** Pobiera komplet kontekstu okna do nakladki */
  'aod.context.get': { request: AodContextGetRequest; response: AodContextGetResponse };
  /** Zwraca podpowiedzi nastepnego kroku dla nakladki. UWAGA: wykaz okien obiecuje te pozycje slowem podpowiedz, nie rozstrzygajac, czy jest to odczyt Operatora, czy zdarzenie wypychane przez rdzen */
  'aod.suggestion': { request: AodSuggestionRequest; response: AodSuggestionResponse };
  /** Przypina proces do obserwacji w nakladce */
  'aod.observe.attach': { request: AodObserveAttachRequest; response: AodObserveAttachResponse };
  /** Odpina proces od obserwacji w nakladce */
  'aod.observe.detach': { request: AodObserveDetachRequest; response: AodObserveDetachResponse };
  /** Rejestracja jedynej encji Konto wlasciciela przy pierwszym uruchomieniu platformy: login, adres e-mail uwierzytelniajacy i haslo. Konto powstaje w stanie NIEPOTWIERDZONYM i pozostaje w nim do chwili potwierdzenia adresu komenda auth.verify — dopiero potwierdzenie wydaje urzadzeniu token dostepu. Sesji ta komenda NIE zaklada. Wykonalna tylko raz; potem odmawia trwale. Powtorzenie hasla jest sprawa formularza klienta, nie kontraktu */
  'auth.register': { request: AuthRegisterRequest; response: AuthRegisterResponse };
  /** Potwierdzenie adresu e-mail uwierzytelniajacego po rejestracji. Przenosi konto ze stanu niepotwierdzonego do potwierdzonego, po czym wydaje urzadzeniu token dostepu — to jest moment, w ktorym Operator wchodzi do platformy po raz pierwszy. Droga potwierdzenia przychodzi listem na adres podany przy rejestracji i wygasa; wygasla droga odmawia i pozwala poprosic o nowa */
  'auth.verify': { request: AuthVerifyRequest; response: AuthVerifyResponse };
  /** Inicjacja odzyskiwania konta adresem e-mail uwierzytelniajacym — jedyna droga odzyskania dostepu przewidziana przez platforme, bo adres jest jedynym elementem tozsamosci niezaleznym od urzadzenia. Serwer wysyla na wskazany adres droge potwierdzenia tozsamosci; nowe haslo ustawia sie komenda auth.reset. Odpowiedz nie zdradza, czy adres pasuje do konta — inaczej komenda mowilaby obcemu, jaki adres ma Operator */
  'auth.recover': { request: AuthRecoverRequest; response: AuthRecoverResponse };
  /** Ustawienie nowego hasla po potwierdzeniu odzyskania konta. Zastepuje dotychczasowy skrot hasla przechowywany poza baza danych i uniewaznia tokeny dostepu wydane przed odzyskaniem — kazde powiazane urzadzenie loguje sie ponownie, a zmiana idzie w swiat zdarzeniem device.changed. Nowej encji Konto nie tworzy: zmienia sie wylacznie material uwierzytelniajacy */
  'auth.reset': { request: AuthResetRequest; response: AuthResetResponse };
  /** Logowanie loginem i haslem albo aktywna metoda dodatkowa: PIN, Windows Hello, adres e-mail uwierzytelniajacy. Metodami dzialajacymi dzis sa HASLO i PIN; hello czeka na pochodzenie z domena po https. Login niesie sie przy metodzie password, bo konto ma nazwe wlasciciela nadana przy rejestracji; metody wlasciwe urzadzeniu tozsamosci nie potrzebuja, bo wskazuje ja material na urzadzeniu. Odmowa wraca kodem bledu not_authenticated. Proba nieudana NIE odmawia nastepnej — nakłada na nia ZWLOKE rosnaca wykladniczo (250 ms, 500, 1000, 2000, 4000, dalej rowno 5000 ms), zerowana przy pierwszym udanym wejsciu. Operator, ktory pomylil haslo trzy razy, wchodzi za czwartym; tylko czeka. Zadnego progu prob i zadnej odmowy 'za duzo prob' tu nie ma i nie bedzie — to byloby bramkowanie (rozstrzygniecie Wlasciciela z 14.08.2026) */
  'auth.login': { request: AuthLoginRequest; response: AuthLoginResponse };
  /** Zaklada metode szybkiego wejscia na wskazanym urzadzeniu — PIN albo klucz Windows Hello. Czynnosc USTAWIEN, wykonalna po zalogowaniu; hasla ta komenda nie zaklada, bo kotwica powstaje przy auth.register. Klucz Hello nie opuszcza TPM urzadzenia, wiec na kazdej maszynie zaklada sie go osobno — i tylko wtedy, gdy interfejs jest podawany z pochodzenia z domena po https. Dzis zalozyc mozna PIN */
  'auth.method.add': { request: AuthMethodAddRequest; response: AuthMethodAddResponse };
  /** Zdejmuje metode szybkiego wejscia z urzadzenia. Ani ostatniej metody, ani hasla zdjac sie nie da — haslo jest kotwica bramki */
  'auth.method.remove': { request: AuthMethodRemoveRequest; response: AuthMethodRemoveResponse };
  /** Zmienia haslo bramki ZE ZNANYM HASLEM BIEZACYM. Drogi odzyskania listem na adres e-mail dzis NIE MA — rdzen poczty nie wysyla, a konta po adresie e-mail nie ma w zakresie 13.08.2026 */
  'auth.password.reset': { request: AuthPasswordResetRequest; response: AuthPasswordResetResponse };
  /** Przedluza sesje bramki jawnie. W Danaco HUB dzieje sie to samo przy kazdym zadaniu HTTP; tu jest komenda, bo transportem jest jedno gniazdo WebSocket */
  'auth.token.refresh': { request: AuthTokenRefreshRequest; response: AuthTokenRefreshResponse };
  /** Wykaz urzadzen powiazanych z kontem wlasciciela. Konto jest jedno, urzadzen dowolnie wiele: komputery, telefony, tablety. Kazde niesie wlasny token dostepu, wiec wykaz jest miejscem, w ktorym Operator widzi, co ma dostep do platformy */
  'device.list': { request: DeviceListRequest; response: DeviceListResponse };
  /** Uniewaznia token dostepu wskazanego urzadzenia — urzadzenie loguje sie ponownie przy nastepnym uruchomieniu. Zmiana idzie do wszystkich polaczonych urzadzen zdarzeniem device.changed, wiec Operator widzi skutek natychmiast na pozostalych ekranach. Tej samej drogi uzywa odzyskanie konta, ktore uniewaznia tokeny wydane przed zmiana hasla */
  'device.revoke': { request: DeviceRevokeRequest; response: DeviceRevokeResponse };
