  'team.list': { request: TeamListRequest; response: TeamListResponse };
  /** Zaklada kopie zespolu pod nowa nazwa; sklad przechodzi bez zmian */
  'team.duplicate': { request: TeamDuplicateRequest; response: TeamDuplicateResponse };
