  'history.load': { request: HistoryLoadRequest; response: HistoryLoadResponse };
  /** Usuwa pozycje historii okna; bez wskazania pozycji czysci cala historie okna */
  'history.delete': { request: HistoryDeleteRequest; response: HistoryDeleteResponse };
  /** Ustawia zasade przechowywania historii dla zakresu */
  'retention.set': { request: RetentionSetRequest; response: RetentionSetResponse };
  /** Zwraca role nadane oknom wraz z wiezia koordynatora */
  'role.list': { request: RoleListRequest; response: RoleListResponse };
  /** Zdejmuje role z okna wraz z wiezia koordynatora */
  'role.remove': { request: RoleRemoveRequest; response: RoleRemoveResponse };
  /** Zwraca uklad sekcji panelu okna */
  'panel.sections.get': { request: PanelSectionsGetRequest; response: PanelSectionsGetResponse };
  /** Zapisuje uklad sekcji panelu okna */
  'panel.sections.set': { request: PanelSectionsSetRequest; response: PanelSectionsSetResponse };
  /** Zwraca wdrozenia okna wraz z ich stanem. Bez tej komendy historia wdrozen znikala po odswiezeniu okna, bo klient odbudowywal ja wylacznie ze zdarzen biezacej sesji */
  'apps.deployment.list': { request: AppsDeploymentListRequest; response: AppsDeploymentListResponse };
  /** Zwraca architekture okna. Odpowiednik odczytu dla apps.architecture.define — bez niego okno po odswiezeniu nie wie, co Operator wczesniej zdefiniowal */
  'apps.architecture.get': { request: AppsArchitectureGetRequest; response: AppsArchitectureGetResponse };
