  /** Oznacza zasob jako ulubiony albo zdejmuje oznaczenie. design.asset.list umial juz filtrowac po ulubionych, ale nikt nie mial jak ich ustawic */
  'design.asset.favorite.set': { request: DesignAssetFavoriteSetRequest; response: DesignAssetFavoriteSetResponse };
  /** Zwraca kompozycje okna wraz z warstwami. design.board.update jechala w jedna strone — po odswiezeniu okna plansza nie wracala */
  'design.board.list': { request: DesignBoardListRequest; response: DesignBoardListResponse };
  /** Odczytuje wlasciwosci obrazu: format, wymiary, glebia, profil barw, rozmiar, metadane EXIF. Czynnosc czytajaca — model uzywa jej, zanim cokolwiek zmieni */
  'image.inspect': { request: ImageInspectRequest; response: ImageInspectResponse };
  /** Przeksztalca obraz geometrycznie: skalowanie, kadrowanie, obrot, odbicie. Wynikiem jest NOWY zasob w magazynie — zrodlo zostaje nietkniete, wiec model moze probowac bez ryzyka */
  'image.transform': { request: ImageTransformRequest; response: ImageTransformResponse };
