  'image.upscale': { request: ImageUpscaleRequest; response: ImageUpscaleResponse };
  /** Usuwa tlo z obrazu, zostawiajac przezroczystosc. Zastepuje wyspecjalizowane narzedzia wycinania; bez silnika odmawia, nazywajac brak */
  'image.background.remove': { request: ImageBackgroundRemoveRequest; response: ImageBackgroundRemoveResponse };
