  'apps.timeline.list': { request: AppsTimelineListRequest; response: AppsTimelineListResponse };
  /** Sprawdza uklad komponentow: komponenty bez polaczen, brakujace zaleznosci i cykle. Dzis pole validationIssues jest zapisywane i oddawane bez wyliczenia, wiec jego pustka nie orzeka o poprawnosci ukladu. Zastrzezenia sa OSTRZEZENIEM, nie brama — nie wstrzymuja pracy w warsztatach */
  'apps.architecture.validate': { request: AppsArchitectureValidateRequest; response: AppsArchitectureValidateResponse };
