/** Cztery srodowiska produktu, zgodnie z kolumna srodowisko.kod. Lista informacyjna, nie brama */
export const KnownModuleIds = ['talkin', 'workspace', 'codestudio', 'multitaskingai'] as const;

/** Rodzaje kanalow znane w chwili wydania kontraktu, zgodnie z kolumna kanal_modelu.rodzaj_kanalu. Lista informacyjna; nowy kanal = nowy wiersz rejestru, nie zmiana kodu */
export const KnownChannelKinds = ['cli', 'api', 'sdk', 'lokalny'] as const;

/** Klucze ustawien uzgodnione przy budowie okna konfiguracji. Lista informacyjna, nie brama — katalog ustawien jest sterowany danymi, wiec nowa pozycja to nowy wiersz, nie zmiana kodu */
export const KnownSettingKeys = ['katalog.roboczy.podstawa', 'katalog.roboczy.wzorzec_sesji', 'tozsamosc.tryb_domyslny'] as const;

/** Klucze rezolwera, pod ktorymi utrwalane sa obszary konfiguracji sesji. Klucz powstaje mechanicznie: "sesja.konfiguracja." + wartosc SessionConfigArea. Konfiguracja sesji nie ma wlasnego rezolwera — idzie tym samym rezolwerem osmiu poziomow i trzech osi, ktory obsluguje config.get i config.set. Lista informacyjna, nie brama */
export const KnownSessionConfigKeys = ['sesja.konfiguracja.model', 'sesja.konfiguracja.account', 'sesja.konfiguracja.provider', 'sesja.konfiguracja.systemPrompt', 'sesja.konfiguracja.tools', 'sesja.konfiguracja.permissions', 'sesja.konfiguracja.mcp', 'sesja.konfiguracja.hooks', 'sesja.konfiguracja.skills', 'sesja.konfiguracja.memory', 'sesja.konfiguracja.projectContext', 'sesja.konfiguracja.conversationContext', 'sesja.konfiguracja.workingDirectory', 'sesja.konfiguracja.additionalDirectories', 'sesja.konfiguracja.environment', 'sesja.konfiguracja.inputOutput', 'sesja.konfiguracja.runtime', 'sesja.konfiguracja.sessionLifecycle'] as const;
